 expect((await capabilities.owner.evaluateWindow('maker',{applicability:scope,validFrom:'2026-02-01T00:00:00',validTo:'2026-03-01T00:00:00',mode:'CURRENT_ADMISSION'})).status).toBe('SATISFIED');
 expect((await capabilities.owner.evaluateWindow('maker',{applicability:{...scope,capabilityType:'EXECUTE'},validFrom:'2026-02-01T00:00:00',validTo:'2026-03-01T00:00:00',mode:'CURRENT_ADMISSION'})).status).toBe('NOT_SATISFIED');
 expect((await capabilities.owner.history('maker',{id})).versions[0]!.facts.source.sourceVersion).toBe('9');
