test('an explicit one-microsecond suspension rejects the whole new window while the original record time remains readable',async()=>{
 const s=await capabilities.endpoint(),entry=capabilities.entry(s),out=await capabilities.apply(await capabilities.input([entry])),id=out.facts[0]!.id,h=await capabilities.owner.history('maker',{id});
 const from='2026-03-01T00:00:00.000000',resume='2026-03-01T00:00:00.000001';
 await capabilities.apply(await capabilities.input([{...entry,action:'SUSPEND',target:{owner:'care-organization/unit-capability',id,expectedHead:'1'},row:{...entry.row,enabled:'N',record_status:'SUSPENDED',valid_from:from,valid_to:null}}]));
 expect((await capabilities.owner.read('maker',{id,businessAt:from})).state).toBe('SUSPENDED');
 await capabilities.apply(await capabilities.input([{...entry,action:'RESUME',target:{owner:'care-organization/unit-capability',id,expectedHead:'2'},row:{...entry.row,enabled:'Y',record_status:'ACTIVE',valid_from:resume,valid_to:null}}]));
 const window={applicability:s,validFrom:from,validTo:'2026-03-01T00:00:00.000002',mode:'CURRENT_ADMISSION' as const};
 const current=await capabilities.owner.evaluateWindow('maker',window);expect(current.status).toBe('NOT_SATISFIED');expect(current.checks).toContainEqual(expect.objectContaining({from,to:resume,reason:'CAPABILITY_SUSPENDED'}));
 expect((await capabilities.owner.evaluateWindow('maker',{...window,mode:'HISTORICAL',recordAsOf:h.versions[0]!.recordedAt})).status).toBe('SATISFIED');
 expect((await capabilities.owner.exact('maker',{id,version:'1'}))).toEqual(h.versions[0]);
 await expect(capabilities.owner.evaluateWindow('maker',{...window,recordAsOf:h.versions[0]!.recordedAt})).rejects.toThrow('CURRENT_RECORD_TIME_REQUIRED');
});

