 const entry={...capabilities.entry(s),rule:{kind:'BOOLEAN_GATE_V1' as const,parameter:pin(approved)},row:{...capabilities.row(s),rule_ref:d.id}},request=await capabilities.prepare(await capabilities.input([entry])),out=await capabilities.owner.applyUnit('maker',request);expect(out.status).toBe('COMMITTED');if(out.status!=='COMMITTED')throw new Error('COMMIT_UNKNOWN');
 const id=out.facts[0]!.id,original=await capabilities.owner.exact('maker',{id,version:'1'}),window={applicability:s,validFrom:'2026-02-01T00:00:00',validTo:'2026-03-01T00:00:00',mode:'CURRENT_ADMISSION' as const};
 const revised=await values.command('maker',{action:'REVISE',requestId:randomUUID(),reason:'TEST deny new usage',target:approved.id,expectedHead:'1',definitionVersionId:d.versionId,definitionDigest:d.reviewDigest,value:{type:'BOOLEAN',value:false},purpose:'BOOLEAN_GATE_V1',validFrom:'2026-01-01T00:00:00',validTo:null,evidenceId:f.artifact.artifactId});
 expect((await capabilities.owner.evaluateWindow('maker',window)).status).toBe('SATISFIED');
 await values.command('reviewer',{action:'APPROVE',requestId:randomUUID(),reason:'TEST approve denied gate',target:revised.id,versionId:revised.versionId,reviewDigest:revised.reviewDigest});
 expect((await capabilities.owner.evaluateWindow('maker',window)).checks).toContainEqual(expect.objectContaining({reason:'PARAMETER_ADOPTION_CHANGED'}));
 const {responseStatus:_,...durable}=out;expect(await capabilities.owner.resumeOutcome('maker',request)).toEqual(durable);expect(await capabilities.owner.exact('maker',{id,version:'1'})).toEqual(original);
 const readyDraft=await values.command('maker',{action:'REVISE',requestId:randomUUID(),reason:'TEST ready again',target:approved.id,expectedHead:'2',definitionVersionId:d.versionId,definitionDigest:d.reviewDigest,value:{type:'BOOLEAN',value:true},purpose:'BOOLEAN_GATE_V1',validFrom:'2026-01-01T00:00:00',validTo:null,evidenceId:f.artifact.artifactId}),ready=await values.command('reviewer',{action:'APPROVE',requestId:randomUUID(),reason:'TEST approved ready gate',target:readyDraft.id,versionId:readyDraft.versionId,reviewDigest:readyDraft.reviewDigest});
 await capabilities.apply(await capabilities.input([{...entry,action:'REVISE',target:{owner:'care-organization/unit-capability',id,expectedHead:'1'},rule:{kind:'BOOLEAN_GATE_V1',parameter:pin(ready)}}]));
 expect((await capabilities.owner.evaluateWindow('maker',window)).status).toBe('SATISFIED');expect(await capabilities.owner.exact('maker',{id,version:'1'})).toEqual(original);
