test('finite Department and Campus impacts preserve original evidence, reserve paused capabilities and recover exact committed END proofs',async()=>{
 const s=await capabilities.endpoint(),entry=capabilities.entry(s),grant=await capabilities.apply(await capabilities.input([entry])),id=grant.facts[0]!.id,unit=await f.owner.history('maker',{id:s.unit.id}),dept=unit.departmentId;
 const pool=new Pool({connectionString:connection,max:1});try{
  const refs=async()=> (await pool.query('select care_organization.capability_department_references($1,$2::jsonb,$3) r',['maker',JSON.stringify([dept]),'NORTH'])).rows[0].r;
  const first=(await refs()).find((r:{id:string})=>r.id===id);expect(first.current).toBe(true);expect(first.acceptedVersions.length).toBeGreaterThan(0);
  const paused={...entry,action:'SUSPEND' as const,target:{owner:'care-organization/unit-capability' as const,id,expectedHead:'1'},row:{...entry.row,enabled:'N' as const,record_status:'SUSPENDED' as const,valid_from:'2026-04-01T00:00:00'}};
  await capabilities.apply(await capabilities.input([paused]));expect((await refs()).find((r:{id:string})=>r.id===id).current).toBe(true);
  const endInput=await capabilities.input([{...paused,action:'END',target:{...paused.target,expectedHead:'2'},row:{...paused.row,record_status:'RETIRED',valid_from:'2026-05-01T00:00:00'}}]),request=await capabilities.prepare(endInput),ended=await capabilities.owner.applyUnit('maker',request);expect(ended.status).toBe('COMMITTED');
  const h=await capabilities.owner.history('maker',{id}),v=h.versions.at(-1)!,ref={owner:'UNIT_CAPABILITY',id,versionId:v.id,...request};
  const result=(await pool.query('select department_master.impact_result($1,$2::jsonb,$3) r',['maker',JSON.stringify(ref),'NORTH'])).rows[0].r;expect(result).toMatchObject({action:'END',safeShrink:true,period:{from:'2026-01-01T00:00:00.000000',to:'2026-05-01T00:00:00.000000'}});
  const current=(await refs()).find((r:{id:string})=>r.id===id);expect(current).toMatchObject({current:false,originalDigest:first.originalDigest,acceptedVersions:first.acceptedVersions});
  const deps=async(from:string,to:string|null)=> (await pool.query('select care_organization.capability_campus_dependencies($1,$2::uuid,$3::timestamp,$4::timestamp,NULL) r',['maker',s.campus.id,from,to])).rows[0].r;
  expect((await deps('2026-02-01T00:00:00','2026-03-01T00:00:00')).find((r:{id:string})=>r.id===id)).toMatchObject({active:true,outstanding:false});expect((await deps('2026-05-01T00:00:00',null)).find((r:{id:string})=>r.id===id)).toMatchObject({active:false,outstanding:false});
  await expect(capabilities.apply(await capabilities.input([{...entry,action:'RESUME',target:{...paused.target,expectedHead:'3'},row:{...entry.row,valid_from:'2026-05-01T00:00:00'}}]))).rejects.toThrow('CAPABILITY_ENDED');
 }finally{await pool.end();}
});


async function populated(enabled:'Y'|'N'='Y',to:string|null=null){const s=await capabilities.endpoint(),entry=capabilities.entry(s);entry.row.enabled=enabled;entry.row.valid_to=to;const out=await capabilities.apply(await capabilities.input([entry]));return {s,entry,id:out.facts[0]!.id};}
function command(a:Awaited<ReturnType<typeof populated>>,action:Exclude<CapabilityEntry['action'],'GRANT'>,head:string,from:string,to:string|null=null):CapabilityEntry{return {...a.entry,action,target:{owner:'care-organization/unit-capability',id:a.id,expectedHead:head},row:{...a.entry.row,valid_from:from,valid_to:to,enabled:action==='SUSPEND'||action==='END'?'N':a.entry.row.enabled,record_status:action==='END'?'RETIRED':action==='SUSPEND'?'SUSPENDED':'ACTIVE'}};}

